
:deep(.ant-form-item) {
  align-items: center;
  &.tip {
    margin-top: -20px;
    color: #ffffff;
  }
}
.helptxt {
  display: flex;
  align-items: flex-start;
  .ant-input {
    background: #212534;
    width: 50%;
    max-width: 280px;
    padding: 10px;
    border: #212534;
  }
  :deep(.ant-form-item-control-input-content) {
    display: flex;
    justify-content: flex-start;
    gap: 10px;
    align-items: flex-start;
  }
}
:deep(.ant-form-horizontal .ant-form-item-label) {
  width: 160px;
}
:deep(.ant-form-horizontal .ant-form-item-control) {
  width: unset;
}
:deep(.ant-form-item .ant-select) {
  width: 280px;
}
:deep(.ant-form-item.select .ant-form-item-control-input) {
  max-width: 280px;
}
:deep(.ant-select-single:not(.ant-select-customize-input)
    .ant-select-selector
    .ant-select-selection-search-input) {
  height: 40px;
}
:deep(.ant-select:not(.ant-select-customize-input) .ant-select-selector) {
  height: 40px;
  padding: 5px 20px;
  background: #212534;
  color: #ffffff;
  border: 0;
}

.withdrawalmethod {
  display: flex;
  justify-content: center;
  align-items: center;
  text-align: center;
  overflow-x: auto;
  padding: 15px 5px;
}
.withdrawal {
  ul {
    padding: 0 0 0 20px;
    li {
      list-style-type: disc;
      margin-bottom: 10px;
    }
  }
  :deep(.ant-steps-item) {
    flex: unset;
  }
  :deep(.ant-steps-item-process .ant-steps-item-icon) {
    background: #2b2b4b;
    border: 1px solid #db7e42;
  }
  :deep(.ant-steps-item-finish .ant-steps-item-icon) {
    background-image: linear-gradient(to right, #de4545, #db7e42);

    border: 1px solid #2b2b4b;
    svg {
      color: #ffffff;
      stroke-width: 5px;
    }
  }
  :deep(.ant-steps-item-finish
      > .ant-steps-item-container
      > .ant-steps-item-content
      > .ant-steps-item-title) {
    color: #db7e42;
  }
  :deep(.ant-steps-item-process
      > .ant-steps-item-container
      > .ant-steps-item-content
      > .ant-steps-item-title) {
    color: #ffffff;
  }
  :deep(.ant-steps-item-title::after) {
    display: none;
  }
}
.step-item {
  color: #ffffff;
  width: 130px;
  // height: 50px;
  line-height: 45px;
  background-color: #2b2b4b;
  text-align: center;
  position: relative;
  border: 2px solid #2b2b4b;
  border-left: 0;
  padding-left: 20px;
  font-weight: bold;
  &::before,
  &::after {
    content: "";
    position: absolute;
    border-top: 23px solid transparent;
    border-bottom: 23px solid transparent;
    top: 0px;
  }
  &::before {
    left: 0;
    top: -2px;
    border-left: 25px solid #24222e;
    border-top: 25px solid transparent;
    border-bottom: 25px solid transparent;
  }
  &::after {
    border-left: 23px solid #2b2b4b;
    right: -23px;
    z-index: 1;
  }
  &.active {
    color: #24222e;
    background: #ffffff;
    border: 0;
    padding-left: 0px;
    &::after {
      border-left: 25px solid #ffffff;
      top: 0;
      right: -25px;
      border-top: 25px solid transparent;
      border-bottom: 25px solid transparent;
    }
  }
  &:first-child::before,
  &:last-child::after {
    display: none;
  }
}
.withdraw-type-item {
  width: 120px;
  margin-right: 10px;
  padding: 20px 20px;
  border-radius: 6px;
  border: solid 1px #484460;
  background: #2b2b4b;
  border-radius: 20px;

  position: relative;
  cursor: pointer;
  img { width: 100%; }
  &.active {
    background: #212534;
    color: #db7e42;
    box-shadow: none;
    filter: drop-shadow(0px 0px 3px #ffffff);
  }
  .type-name {
    line-height: 15px;
    margin: 10px 0 0;
    overflow-wrap: break-word;
  }
  .promo {
    position: absolute;
    right: 0;
    top: 0;
    background-repeat: no-repeat;
    background-size: 100%;
    background-position: top center;
    top: -8px;
    right: -1px;
    background: linear-gradient(to right, #de4545, #db7e42);
    padding: 5px;
    color: #ffffff;
    font-size: 12px;
    line-height: 10px;
    border-radius: 0 10px;
    font-weight: bold;
    ::after {
      position: relative;
    }
  }
}
.withdraw-btn {
  margin: 30px auto;
  &.cancel {
    margin-right: 60px;
  }
}
